Body:
Still reproducible on v1.14.19

Example working custom tool:

```ts
$ cat ~/.config/opencode/tools/searxng.ts 
import { tool } from "@opencode-ai/plugin"

const SEARXNG_URL = "https://searx.example.org/search"

export default tool({
  description: "Search the web using self-hosted SearXNG instance",
  args: {
    query: tool.schema.string().describe("Search query"),
    limit: tool.schema.number().optional().describe("Max number of results (default 10)"),
  },

    const limit = args.limit || 10
    const url = `${SEARXNG_URL}?q=${encodeURIComponent(args.query)}&format=json`
    const raw = await Bun.$`curl -k -s ${url}`.text()
    const data = JSON.parse(raw)
    const results = (data.results || []).slice(0, limit)
    return JSON.stringify(
      results.map((r) => ({
        title: r.title,
        url: r.url,
        engine: r.engine,
        content: r.content || "",
      })),
      null,
      2,
    )
  },
})
```

The tool always runs without asking for permission, for example when prompted with `do a searxng search for "example topic"`

The workaround (adding `await ctx.ask`) mentioned by @peltax doesn't seem to work either, the tool still runs without asking for permission.
